def add(key,model,scenario,steps,obs,concl,exam,pitfall,q,a,example=None,aliases=[],controls=None,params=None):
 e=by['phy-'+key]; r=dict(id=e['id'],subject='physics',term='8上',chapter=chap.get(e['section'].split('.')[0],chap['0']),section=e['section'],title=e['title'],kind=e['kind'] if e['kind'] in ['学生实验','演示实验','小实验','拓展探究'] else '小实验',tags=[e['textbookColumn']],sourceIds=e['sourceIds'],objective=e['focus'],apparatus=e['apparatus'],steps=steps.split('|'),observations=obs.split('|'),conclusion=concl,examPoints=exam.split('|'),pitfalls=pitfall.split('|'),questions=[dict(q=q,a=a)],safety=[e['notes']] if any(k in e['notes'] for k in ['勿','禁止','安全','教师','低压','烫','激光']) else ['使用对应教学器材，涉及加热、玻璃或光源时由教师指导。'],model=model,modelParams=dict(scenario=scenario,variant=key,**(params or {})),modelNote='教学模型突出本实验变量关系；示意物体、声波与光线不按真实比例绘制，数值不替代实际测量。',controls=controls or [])
 if example:
  g,p,c,ans=example;r['workedExample']=dict(title='规范例题',given=g,steps=[dict(title='整理条件',text=g),dict(title='选用依据',text=p),dict(title='代入求解',text=c),dict(title='写出结论',text=ans)],answer=ans)
 else:r['workedExample']=dict(title='规范作答',given=q,steps=[dict(title='明确要比较的条件',text=e['focus']),dict(title='指出观察证据',text=obs.split('|')[0]),dict(title='解释现象',text=concl),dict(title='完整回答',text=a)],answer=a)
 records.append(r)
 for src in [e['id']]+['phy-'+x for x in aliases]:
  v=by[src];coverage.append(dict(activityId=src,activity=v['title'],section=v['section'],printedPages=v['printedPages'],column=v['textbookColumn'],implementationId=r['id'],sourceUrl=v['sourceUrl'],verification=v['verification'],implementationRelation='primary' if src==e['id'] else 'same-principle-variant'))
# Intro and measuring
add('cold-water-reboil','phase','boiling','观察瓶内仍热但停止沸腾的水。|在模型中降低水面上方的压强。|比较水温与新的沸点。','压强降低后，原本停止沸腾的热水可以再次沸腾。','液体沸点随外界压强降低而降低，重新沸腾不代表水温升高。','水沸腾同时需要达到当时沸点并继续获得汽化所需能量','冷水并非直接把瓶内的水加热','向瓶外浇冷水，瓶内水为何可能再沸腾？','冷却使部分水蒸气液化，瓶内压强降低，水的沸点随之下降。',params={'initial':90})
add('funnel-ball','pressure','flow','把球置于倒置漏斗下方。|在模型中比较停止与持续吹气。|观察球和漏斗附近气流方向。','适当气流条件下，球可能暂时被托持而不掉落。','流动气体可造成压力差和气动力；实际托球涉及复杂流场。','只能用流体作用作定性解释，不把简单伯努利式当成精确托力','吹气强弱与球稳定性不是任意范围单调关系','球不掉落是否意味着没有重力？','不是，重力仍向下，向上的气动力在稳定状态下与其平衡。')
add('pendulum-period','energy','pendulum','用小摆角释放摆球。|记录多个完整往返的总时间。|用总时间除以次数，并改变摆长复测。','小摆角下重复摆动时间较稳定；摆长改变会影响周期。','测多次周期总时间再平均，有助于减小启动停止的相对影响。','一次完整摆动须回到相同位置且运动方向相同','不能把一次单向摆动算成一个周期','20次完整摆动用40.0 s，周期是多少？','周期为2.00 s。',('20次完整摆动共40.0 s。','T=t/N。','T=40.0/20=2.00 s。','单次周期2.00 s。'))
add('ruler-length','measurement','length','根据物体大小选择量程与分度值。|零刻度线与物体一端对齐，视线垂直刻度面。|读取另一端并估读到下一位，记录单位。','错误视线或误把尺端当零点会造成读数偏差。','长度测量必须同时记录数值和单位，并与刻度尺精度相适应。','可使用非零起点，两端读数相减|身体尺需先标定','不把测量值与真实值完全等同','物体两端对准1.20 cm和6.45 cm，长度是多少？','长度为5.25 cm。',('两端读数1.20 cm、6.45 cm。','长度=终点读数−起点读数。','L=6.45−1.20=5.25 cm。','长度5.25 cm。'),aliases=['body-ruler','height-foot','court-measure'])
add('stopwatch-pulse-step','measurement','time','明确计时事件的起止。|记录多次脉搏或多个步行周期总时间。|计算平均间隔并比较重复测量。','短时间事件的人工反应影响占比更大。','秒表测量应统一起止标准，累计计时可减小相对误差。','仪表分度值与人为反应时间是不同误差来源','不能把脉搏次数直接当作秒数','30次脉搏间隔总计24 s，平均间隔多少？','若记录的是30个完整间隔，平均0.80 s。',('记录30个完整脉搏间隔，总时间24.0 s。','平均间隔=t/N。','24.0/30=0.800 s。','平均间隔0.800 s。'))
add('coin-size','measurement','length','用两块平直挡板夹住硬币两侧。|测两内侧间距作为直径。|也可滚动一周测周长，并比较方法。','辅助工具使曲面物体边缘更容易定位。','间接测量可把难测的几何量转成容易读取的长度。','挡板必须与尺垂直|滚动一周要避免滑动','不能把半径当直径','为什么测硬币直径常需要挡板？','挡板能把圆形边缘转化为两条易对齐刻度的边线，降低定位困难。',aliases=['syringe-diameter'])
add('paper-thickness','measurement','length','把相同纸张压平并数清张数。|测量多张总厚度。|总厚度除以张数，并用密绕金属丝作方法对照。','累计厚度比单张厚度更容易用毫米尺读准。','累积法把小量放大后再平均，可以减小相对测量影响。','不得把封面或纸间空隙算入|密绕线圈应无间隙、无重叠','总厚度除的是张数，不是页码数','100张纸厚8.0 mm，单张厚度多少？','约0.080 mm。',('100张纸总厚8.0 mm。','单张厚度d=L/N。','d=8.0/100=0.080 mm。','单张约0.080 mm。'),aliases=['wire-diameter'])
add('incline-speed','incline','speed','让小车从同一起点静止释放。|测量全程与各分段的路程和用时。|分别用对应s和t求平均速度并比较。','后半程与前半程路程相等，但后半程用时更短。','小车下滑速度会变化；不同区间的平均速度应分别计算。','v=s/t|全程速度不能直接平均两个半程速度','改变参数后不能混用旧时间','全程0.80 m用2.00 s，平均速度多少？','全程平均速度0.40 m/s。',('s=0.80 m，t=2.00 s。','v=s/t。','v=0.80/2.00=0.40 m/s。','平均速度0.40 m/s。'))
add('sensor-speed','motion','uniform','设置位置采样的相同时间间隔。|记录连续位置读数。|计算相邻区间的路程与时间比并画图。','相等时间内距离增量相同表示匀速；增量变化表示快慢变化。','位置—时间数据能够反映运动速度与变化趋势。','图像斜率与速度有关|传感器读数仍有分辨率限制','不能把位置直接当成路程增量','0.5 s内位置从0.20 m到0.80 m，平均速度多少？','此段平均速度1.2 m/s。',('同一直线同向运动，位置从0.20 m变为0.80 m，间隔0.50 s。','v=Δs/Δt。','v=(0.80−0.20)/0.50=1.2 m/s。','平均速度1.2 m/s。'),aliases=['drip-timer'])
add('walking-speed','motion','uniform','选择已测长度的平直路线。|按统一标准测步行用时。|计算平均速度，再用速度估算相似步行条件下的路程。','步行节奏改变时平均速度也会改变。','速度测量要有对应路程和时间；估测需说明适用条件。','骑行里程差与步行路线均可用s/t|平均速度不要求全程匀速','不能把静止休息时间随意删去而不说明区间','走60 m用50 s，平均速度是多少？','平均速度1.2 m/s。',('路程60 m，时间50 s。','v=s/t。','v=60/50=1.2 m/s。','平均速度1.2 m/s。'),aliases=['milestone-speed'])
# Sound
add('rubber-vibration','sound','amplitude','拨动绷紧橡皮筋并观察。|轻触喉部比较发声与停止发声。|在鼓面放轻小颗粒显示微小振动。','发声物体在振动；振动停止后声源不再持续发声。','声音由物体振动产生，可用放大现象帮助观察。','橡皮筋、声带、鼓面分别是声源|转换法显示微小振动','声源停止后已传播的声波不会立刻消失','鼓面放米粒的作用是什么？','把鼓面不易直接看清的振动，转换成颗粒可见的运动。',aliases=['vocal-cord','drum-grains'])
add('vacuum-bell','sound','vacuum','将发声铃置于密闭罩。|逐渐减少罩内空气，观察铃的振动和声音。|恢复空气作对照。','空气减少时声音减弱，铃仍可振动。','声音传播需要介质，结合抽气实验推理真空不能传声。','实验加科学推理|不能把未抽尽空气称为绝对真空','不能说声音减弱说明铃不再振动','为什么需要观察铃是否仍在工作？','排除声源停止发声的原因，才能研究空气对声音传播的作用。')
add('water-wave-analogy','sound','medium','轻点水面形成短促扰动。|观察波纹向外扩展。|用浮标比较传播方向和局部振动方向。','波纹向外传播，浮标主要在原处附近起伏。','波能够传播扰动和能量，介质整体并不随波一路向外搬运。','类比有助于理解声波，但声波并非水面波','不要把波速等同于浮标移动速度','波纹到远处是否表示原来的水全部流到那里？','不是，主要是扰动传到远处，而水在平衡位置附近运动。')
add('desk-sound','sound','medium','一人轻刮桌面，另一人在固定位置听。|比较耳朵贴桌与离开桌面的效果。|讨论可能的传播路径。','耳朵贴桌时可以更明显听到轻刮声。','固体可以传声，声音不只通过空气传播。','比较时固定声源强弱与距离','听起来更响不直接证明此实验测得固体声速','为什么耳朵贴桌能听到较轻的声音？','振动通过桌面传到耳部，增加了固体传声路径。')
add('cup-telephone','sound','medium','用棉线连接两只纸杯。|拉紧线后在一端轻声说话。|让线松弛或被轻握，再比较听感。','拉紧且不受阻挡的线传声效果通常更明显。','杯底和线的振动能够传递声音。','声源、传声物和接收部分要区分','不能把线电话解释成电流通信','握住线后声音为什么可能减弱？','握住线会抑制振动并增加能量损耗，使传到另一杯的振动减弱。')
add('ruler-pitch','sound','pitch','固定钢尺一端，先保持较长伸出长度。|用相近幅度拨动，再缩短伸出长度。|比较振动快慢、声音与同时间尺度波形。','伸出长度缩短时，振动通常更快、音调更高。','音调由频率决定，频率越高，音调越高。','同时间内振动次数与频率关联','大力拨动主要改变振幅，不能直接作为提高音调的方法','两个波形时间范围相同，振动次数多者音调如何？','频率较高，音调较高。',aliases=['frequency-waveform'])
add('amplitude-ball','sound','amplitude','用悬线把轻球置于音叉附近。|先轻敲音叉观察弹开程度。|再较重敲击并比较声音与球的偏移。','较强敲击时振幅较大，球被弹开更明显。','振幅影响响度；球的运动把音叉振动放大显示。','响度还受距离等因素影响','不要把响度大说成音调高','这项实验为什么要固定听者位置？','响度受距离影响，固定位置便于比较振幅改变的作用。')
add('timbre-waveform','sound','timbre','使不同声源发出相近音调和响度的声音。|使用相同时间尺度显示波形。|比较波形形状而非只数波峰。','周期相近时，波形形状仍可能不同。','音色与声源振动的具体形式有关，可用波形差异辅助辨认。','音调、响度与音色是不同维度','不能以音色不同推出基频一定不同','不同乐器演奏同一个音，为什么仍能辨别？','它们的振动组成和波形不同，形成不同音色。',aliases=['instrument-observation'])
add('bottle-xylophone','sound','pitch','向相同玻璃瓶加入不同水量。|用相同方式轻敲瓶体。|按声音高低排列并重复比较。','敲击相同瓶体时，加水通常使振动频率降低。','改变振动系统的条件可以改变音调；敲击瓶体与吹瓶口的声源不同。','敲瓶主要研究瓶与水的振动|吹瓶主要研究空气柱','不能把吹瓶的水量规律直接用于敲瓶','为什么必须先说清是敲瓶还是吹瓶？','两种方式的主要振动系统不同，水量对音调的影响规律可能相反。')
add('piston-flute','sound','pitch','保持吹气方式近似不变。|移动活塞改变有效空气柱长度。|比较不同位置的音调。','空气柱变短时，常见哨管音调升高。','空气柱的振动条件决定其发声频率。','管口边界条件会影响共鸣模式','不能把吹气越强普遍等同于音调越高','活塞向内推使空气柱缩短，音调通常怎样？','通常升高，因为对应的主要共振频率增大。')
add('speaker-candle','sound','amplitude','将可视指示物置于扬声器附近。|播放低频声音并观察指示物运动。|保持距离，改变振幅比较效果。','声音较强时，轻小指示物或烛焰可发生振动。','声波能够传递能量。','能量传递与信息传递是声音的两类作用','不可把明火靠近电器作为家庭操作','声源没有碰到指示物，为什么它会动？','振动通过空气传递，声波把能量传给指示物。')
add('noise-waveform','sound','noise','记录音叉和刮擦声。|用同样时间尺度显示波形。|比较规律性并结合使用情境判断噪声。','刮擦声波形通常更杂乱；环境中的噪声还与是否干扰活动有关。','物理上噪声常对应不规则振动；环境角度看，干扰生活学习的声音也是噪声。','悦耳音乐在不适当场合也可成为噪声','不能只按个人是否喜欢判定波形的规则性','规则振动发出的音乐一定不是环境噪声吗？','不一定，若妨碍休息学习，也可构成环境噪声。')
add('soundproof-room','sound','noise','明确声源、传播路线和测量位置。|比较不同衬材与缝隙条件。|保持同一声源和距离，多次记录相对强度。','增加合适隔声措施通常降低接收位置的声音。','控制噪声可在声源、传播途径和人耳处采取措施。','测试需固定音量与测量位置|吸声与隔声机理并非完全一样','本模拟相对强度不是实测分贝|脉搏观察不能据一次相关性断言因果','怎样公平比较两种隔音材料？','保持声源、房间尺寸、开口和接收位置相同，只更换材料并重复测量。',aliases=['noise-survey','noise-pulse-observation','earmuff-design'])
# Thermal
add('temperature-sensation','measurement','temperature','先分别接触安全范围的冷水与温水。|再把两只手接触同一杯中温水。|用温度计检验实际温度。','同一杯水可能给两只手不同的冷热感觉。','感觉受适应影响，测温应依靠经标定的仪器。','温度表示冷热程度|感觉不可靠不等于完全无用','不以皮肤感觉替代安全温度判断','同一杯水一只手觉得冷、一只手觉得热，水温矛盾吗？','不矛盾，水温相同；两只手先前温度和适应状态不同。')
add('homemade-thermometer','measurement','temperature','用密封储液瓶连接细管。|改变周围温度观察液面。|讨论如何标出标准温度点与刻度。','在合适液体和温度范围内，升温时液面上升。','液体热胀冷缩可转换为液柱长度变化，标定后可用于测温。','细管放大液体体积变化|未标定装置只能判断变化不能精确读温度','不能认为所有物质体积随温度都等比例变化','为什么常把细管做得较细？','相同体积变化对应更大液面高度变化，便于观察。')
add('water-thermometer','measurement','temperature','检查量程和分度值。|让感温部分充分接触待测液体且不碰容器底壁。|待示数稳定后在液体中读数并记录。','探头接触不充分或碰热杯壁时读数可能偏离液体代表温度。','正确测温需保证热接触、足够响应时间和合适读数方式。','普通实验温度计通常不能取出后再读','量程不合适不能靠估计补救','为什么要等温度计示数稳定？','温度计需要与被测物体达到近似热平衡，过早读数会有响应误差。',aliases=['fridge-temperature','classroom-temperature'])
add('bimetal-thermometer','thermal','conduction','观察两层不同金属组成的薄片。|比较温度改变前后的弯曲。|把弯曲转换成指针偏转并讨论标定。','温度变化时两种金属膨胀程度不同，组合片弯曲。','不同材料热膨胀差异可以用于温度指示。','指针方向取决于两层材料与连接方式','不能仅凭温度升高断言总向左弯','两种金属为什么会使片弯曲？','它们膨胀量不同却结合在一起，受到相互约束而形成弯曲。')
add('ice-melting','phase','melting','把冰水混合物置于较暖环境。|记录温度并观察冰量变化。|比较冰未熔完与全部熔化后的温度。','冰和水共存并充分接触时，温度接近0 ℃；冰量逐渐减少。','晶体熔化时吸热但温度可保持不变。','吸热不一定升温|这里需正常压强和近似纯净物条件','不能把杯壁温度当冰水混合物温度','冰在减少而温度不变，是否说明没有吸热？','不是，吸收的热量用于物态变化。')
add('melting-curves','phase','melting','分别对晶体与非晶体样品缓慢加热。|按相同间隔记录温度与状态。|绘制曲线并比较熔化阶段。','晶体可出现温度近似不变的熔化平台，石蜡等材料常逐渐变软。','晶体有确定熔点；典型非晶体没有确定熔点。','图像平台需结合状态变化判定|用水浴使加热更均匀','本数值模型若用水/冰参数，不可伪称海波的实际曲线','怎样从曲线判断某样品是否有确定熔点？','观察固液共存并持续吸热时是否存在稳定温度平台，同时排除实验条件变化。')
add('freezing-mixture','phase','freezing','比较纯水与水酒精混合物。|观察在相同低温环境中的状态。|讨论成分对凝固温度的影响。','混合物在纯水通常结冰的温度附近仍可能保持液态。','混合物的凝固行为与纯水不同，凝固温度受成分影响。','0 ℃是特定条件下纯水的凝固点','不能把所有液体凝固点都写成0 ℃','液体低于0 ℃仍不结冰，一定测温错误吗？','不一定，它可能不是纯水，或者存在其他影响凝固的条件。')
add('alcohol-bag','phase','condensation','观察密封软袋内少量液体。|在安全温水模型中升温，再降温。|比较液体、气体和袋体积变化。','受热时部分液体汽化，降温后部分气体液化。','汽化吸热、液化放热，物态变化可影响密闭软袋体积。','袋变大并不意味着质量增加','不能将蒸气与可见白雾混淆','软袋冷却后为什么可能变瘪？','部分蒸气液化，气体物质的量减少，外界压力使软袋收缩。')
add('boiling-water','phase','boiling','连续给水加热，按相同间隔测温。|观察水中气泡变化。|沸腾后继续记录，再停止加热。','达到沸点并持续加热时，水大量汽化而温度近似不变。','沸腾是液体内部和表面同时发生的剧烈汽化，需要持续吸热。','沸点受压强影响|气泡上升时大小变化与周围水温相关','不能把水达到100 ℃作为任何条件下沸腾的充分条件','沸腾后继续加热，水温为什么近似不变？','输入能量主要用于汽化，而不是继续提高液体温度。')
add('paper-pot','phase','boiling','在模拟中比较干纸受热与盛水纸容器受热。|观察与水接触部分温度。|分析水吸热对纸温度的限制。','有水接触且加热适当时，纸的温度可能保持在着火温度以下。','水持续吸热使接触部分不易升到燃点，不能据此认为纸不可燃。','纸锅烧水是传热与沸腾共同作用','不能让纸容器烧干，也不能把课堂现象当安全烹饪方法','纸锅没有立即燃烧，是否说明纸不是可燃物？','不是，关键是有水时纸的温度可能未达到燃点。')
add('evaporative-cooling','phase','evaporation','比较干燥温度计与表面湿润温度计。|在同样环境中记录变化。|改变空气流动或液面面积并对照。','表面液体蒸发时温度可能降低，适当通风会加快蒸发。','蒸发吸热，蒸发快慢受温度、面积和空气流动等影响。','控制变量比较蒸发条件|降温效果也与湿度有关','不能认为吹风必然使所有物体降到室温以下','湿纱布加通风为何能帮助降温？','水蒸发吸热，通风带走附近水蒸气，有助于持续蒸发。',aliases=['evaporative-food-cooler'])
add('cold-bottle-condensation','phase','condensation','比较冷瓶与常温瓶外壁。|观察水珠首先出现的位置。|分析水蒸气来源并用不同水温杯作对照。','冷表面附近可出现外界空气中的水蒸气液化形成的水珠。','水蒸气遇冷液化，并不一定来自容器内部。','判断内外壁、温差与蒸气来源','瓶外水珠不等于瓶内水渗出','密封冰水瓶外壁的水从哪里来？','通常来自周围空气中的水蒸气，在冷瓶表面液化。',aliases=['three-cup-condensation'])
add('iodine-sublimation','phase','sublimation','在密封模型中温和加热固态碘。|观察有色气体。|冷却后观察固体重新出现。','固态碘可直接变为气态，冷却后又形成固体。','固态与气态直接转化分别叫升华和凝华。','升华吸热，凝华放热','没有明显液态阶段不能称为汽化与凝固','冷却后出现的固态碘经历了什么变化？','气态碘直接转为固态，属于凝华。')
add('frost-can','phase','sublimation','在容器内部用冰盐模型降低外壁温度。|观察外壁固体冰晶。|比较外壁是否先出现液态水。','足够冷的外壁可能出现霜状冰晶。','空气中的水蒸气可直接凝华成固体冰晶。','霜与露所对应的末态不同','不能把所有外壁结冰都断言为直接凝华，需看有无先液化','霜是由杯内的盐跑到外面形成的吗？','不是，通常由空气中的水蒸气在冷表面形成冰晶。')
add('kitchen-phase','phase','boiling','选择烧水、锅盖水滴或食物冷却等现象。|记录发生变化的位置和物态。|设计控制变量比较保温、加盖等方案。','锅内汽化与较冷锅盖上的液化可同时发生。','厨房中的物态变化伴随吸放热，可用于分析节能和防烫。','白气是小液滴|蒸气液化放热可能造成烫伤','不能仅凭沸腾剧烈就判断水温更高','锅盖上的水滴属于哪种物态变化？','水蒸气遇到较冷锅盖变成液态水，属于液化。')
# Optics
add('light-straight','optics','straight','使窄光束通过均匀水体或玻璃。|从侧面借散射观察路径。|改变光束方向并比较介质内部路径。','光在同一种均匀介质内部沿直线传播。','光的直线传播有同种均匀介质这一条件。','看见光路依赖部分光散射进入眼睛','不能漏掉介质均匀这一条件','水中能看见光路是否说明光只沿朝眼睛方向传播？','不是，主光束向前传播，少量散射光进入眼睛使路径可见。')
add('pinhole-image','optics','pinhole','将小孔、物体和屏按顺序放置。|观察屏上的像。|改变物距或屏距并比较大小与亮度。','像通常上下左右颠倒；增大孔屏距时像变大、变暗。','小孔成像由光沿直线传播形成倒立实像。','像形状由物体决定，不由孔形直接决定','孔越大不一定越清晰','物高10 cm、物孔距50 cm、屏孔距20 cm，像高多少？','像高4 cm且倒立。',('物高10 cm，物孔距50 cm，孔屏距20 cm。','相似三角形：像高/物高=像距/物距。','像高=10×20/50=4 cm。','得到约4 cm高的倒立实像。'))
add('hand-shadow','optics','shadow','让不透明物体位于光源和屏之间。|改变遮挡物到光源的距离。|比较点光源与面光源下影子边界。','遮挡物靠近光源时影子可变大；面光源可能出现半影。','影是光被遮挡造成的暗区，几何位置决定大小。','影与小孔成像不同','不要把影子的方向称为透镜成像倒立','物体靠近点光源，屏上影子通常怎样变化？','在光源和屏位置不变时，影子通常变大。')
add('reflection-law','optics','reflection','将可折纸板竖直放在镜面上。|改变入射角测量反射角。|折转一侧纸板并交换入射与反射方向。','反射角等于入射角；反射光线与入射光线分居法线两侧。','反射光线、入射光线和法线在同一平面内，光路可逆。','角度以法线为基准|折纸板是检验共面关系','不把光线与镜面的夹角直接当作入射角','光线与镜面成30°，反射角是多少？','入射角60°，反射角也是60°。',('入射光线与镜面夹角30°。','法线垂直镜面，反射角等于入射角。','入射角=90°−30°=60°；反射角=60°。','反射角60°。'))
add('diffuse-reflection','optics','reflection','把光照到平面镜与白纸。|从不同方向观察明暗。|用微小面元解释粗糙表面反射。','镜面反射较集中；粗糙表面可把光反射向多个方向。','漫反射的每一条光线仍遵循反射定律。','从多方向看清书本依赖漫反射','不要说漫反射不遵守反射定律','为什么在多个方向都能看见白纸？','纸面微观粗糙，各小面的反射方向不同，使不同方向的人都能接收到光。')
add('retroreflector','optics','retroreflection','观察互相垂直的镜面单元。|追踪一次和两次反射的方向。|改变入射方向比较出射光。','在合适几何结构中，光经多次反射可大致朝来路返回。','回归反射器利用多次反射提高反光可见性，本身通常不发光。','自行车反光尾灯与主动发光灯不同','不可声称所有角度都完全返回光源','没有电池的反光尾灯为什么也很亮？','它把外来车灯光较集中地反射回附近观察方向。')
add('plane-mirror','optics','mirror','竖直放置薄玻璃板。|用等大物体在板后移动，寻找与像重合的位置。|比较物像距离并用屏尝试承接。','像与物等大，关于镜面对称；光屏不能承接该像。','平面镜成正立等大的虚像，像距等于物距。','透明玻璃便于看到替代物|等大物体用于比较像大小','玻璃未竖直会造成替代物始终难以重合','人离平面镜1.5 m，人与像相距多少？','人与像相距3.0 m。',('物到镜距离1.5 m。','像距等于物距。','物像距离=1.5+1.5=3.0 m。','人与像相距3.0 m。'))
add('spoon-mirrors','optics','curved-mirror','观察勺子凸面和凹面中的像。|改变脸与勺子的距离。|与平面镜的成像特点比较。','凸面通常形成正立缩小像；凹面成像会随距离变化。','曲面镜各处法线不同，成像可不同于平面镜。','不能把平面镜等大规律直接用于曲面镜','勺面并非标准球面镜，不能用理想曲面公式伪称精密结果','为何勺子两面看到的像不一样？','两面的曲率方向不同，反射光束会聚或发散的情况不同。')
add('periscope','optics','periscope','把两面平面镜平行放在管道两端。|调整镜面使光两次改变方向。|追踪物体到眼睛的光路。','两次反射可绕过遮挡改变观察高度。','潜望镜利用平面镜反射来改变传播方向。','每一次反射都满足反射定律','只画一条反射而漏掉另一面镜会使光路不完整','潜望镜是否靠折射改变光路？','普通双平面镜潜望镜主要靠两次反射。')
add('refraction-law','optics','refraction','使光从空气斜射入水或玻璃。|测量入射和折射方向。|改变入射角并反向传播比较。','从空气进入水或玻璃时，斜入射光通常向法线偏折。','光跨越不同介质界面时会折射，光路可逆。','垂直入射时方向可不改变|速度仍可能改变','不要把折射角误写成总小于入射角，需比较介质','光从水斜射入空气，折射角通常更大还是更小？','未发生全反射时，通常比入射角大。',aliases=['coin-reappears','bent-chopstick','water-spot'])
add('gradient-saline-ray','optics','gradient','在模型中建立随高度变化的盐水折射率。|让光斜向进入。|比较存在梯度与搅匀后的光路。','介质光学性质随位置改变时，光路可逐渐弯曲。','光沿直线传播的条件不满足时，路径可能弯曲。','区分均匀介质内直线与非均匀介质中渐变光路','弯曲不是重力直接把光压弯的课堂解释','搅匀后路径为什么可能接近直线？','搅匀减小折射率的空间差异，使介质更接近均匀。')
add('prism-spectrum','optics','dispersion','用窄白光照射三棱镜。|在屏上观察光带。|比较各色光的偏折与组合光。','白光经过棱镜后可分成不同颜色的光带。','白光由多种色光组成，不同色光在介质中的折射不同。','色散不是棱镜生成新的颜色|可见光谱有连续性','不能把红绿蓝三原色等同于光谱只有三色','三棱镜为什么能把白光分开？','不同色光的折射程度不同，出射方向分离。',aliases=['water-mirror-spectrum'])
add('rgb-mixture','optics','rgb','分别调节红、绿、蓝光的相对强度。|让色光在同一区域叠加。|记录不同组合下的颜色。','适当比例的红绿蓝光可合成白光。','色光混合与颜料混合规律不同。','色光三原色是红绿蓝','不能把两种颜料的混色结果直接套到发光屏','红光和绿光适当混合可出现什么颜色？','可呈黄色；这是色光叠加的结果。')
add('infrared-heating','thermal','heating','把光谱投到可检测区域。|比较红色可见光边缘外与对照位置的温度响应。|解释看不见光却能升温的现象。','红端外侧也可能出现可测的温度变化。','红外辐射不可被人眼直接看见，但能够传递能量。','不可见不等于不存在|用温度变化作为间接证据','不能根据温升证明那里全无可见光杂散影响','红端外温升能支持什么结论？','说明可见红光之外仍有能够携带能量的辐射。')
# Lens
add('lens-rays','lens','convex','辨认透镜中间与边缘厚度。|让平行光通过凸透镜和凹透镜。|标出会聚焦点或反向延长线交点。','凸透镜使平行光会聚，凹透镜使平行光发散。','透镜对光束的会聚或发散作用取决于其光学性质。','凹透镜的虚焦点不是实际光线交点|焦点到光心是焦距','不能把所有经凸透镜的光都画成经过焦点','哪类入射光经凸透镜后通过焦点？','与主光轴平行的近轴光线，经理想凸透镜后通过像方焦点。',aliases=['focal-length','parallel-light-source'])
add('convex-imaging','lens','convex','先使物体、光心和光屏中心近似同高。|分区改变物距并寻找清晰像。|记录像距、大小、方向与能否用屏承接。','物距跨过焦距和二倍焦距时，像的性质发生变化。','凸透镜成像规律取决于物距与焦距关系。','u>2f缩小实像，f<u<2f放大实像，u<f正立放大虚像','不要在物距小于焦距时反复移屏寻找可承接实像','f=10 cm，u=30 cm，像有什么特点？','像距15 cm，是倒立缩小实像。',('理想薄凸透镜f=10 cm，u=30 cm。','1/f=1/u+1/v（模型计算公式）；课堂也可按物距区间判断。','1/v=1/10−1/30=1/15，v=15 cm。','像位于f与2f之间，是倒立缩小实像。'),aliases=['magnifier-near-far','model-camera','projector-image','magnifier-image','lens-position-swap'])
add('bottle-lens','lens','convex','通过盛水的透明圆柱瓶观察笔。|移动笔与瓶子的距离。|比较水平方向与竖直方向的变形。','圆柱形水体主要在一个方向产生明显会聚作用。','不同曲率方向的折射作用不同，圆柱水瓶并非普通球面凸透镜。','区分横向放大与完整二维等比例放大','不能用单一放大率冒充所有方向的真实成像','为什么水瓶可能只使笔在一个方向明显变形？','圆柱曲面在不同方向的曲率不同，对光线会聚的作用也不同。')
add('covered-lens','lens','convex','先得到清晰实像。|遮住透镜一部分而不改变位置。|比较像的完整性、亮度和位置。','像通常仍完整，但明显变暗。','物体各点可经透镜多个部位成像，遮挡部分减少通过的光。','遮透镜不同于遮物体','不是遮一半透镜就只剩半个像','遮住透镜上半部会让像的下半部消失吗？','通常不会，完整像仍可形成，但亮度降低。')
add('near-point','lens','eye','选择清晰文字作为目标。|缓慢改变观察距离。|记录可以看清的最近距离并比较重复观察。','不同观察者的清晰观察范围可能不同。','眼睛的调节能力有限，近点与眼的光学状态有关。','近点观察不是医学验光|不以一次观察诊断近视','不要强迫长时间近距离用眼','近点测得较近能否独立诊断眼睛完全健康？','不能，课堂观察只涉及一项功能，不能替代专业检查。')
add('spectacle-power','lens','convex','选择可作为凸透镜的老花镜片。|用安全平行光模型或远物近似测焦距。|将焦距换成米再估算镜片度数。','焦距越短，对应正焦度越大。','透镜焦度D=1/f，眼镜常用度数为100D，f以米计。','米与厘米不能混用|镜片组合和真实验光更复杂','不能把估算用于自行配镜','焦距0.50 m的正透镜约多少度？','约+200度。',('正透镜焦距f=0.50 m。','D=1/f；度数=100D。','D=2 m⁻¹，度数=+200度。','约+200度；仅作光学示例。'))
add('hyperopia-correction','lens','hyperopia','用透镜和固定光屏模拟眼睛。|使像位于屏后，模拟远视成像偏差。|在前方加入适当凸透镜使像回到屏上。','加合适凸透镜后光线会聚能力增强，可使清晰像回到视网膜位置。','远视通常用凸透镜矫正；近视通常用凹透镜矫正。','远视成像落在视网膜后|教材模型不能替代医学诊断','不要交换近视和远视的镜片类型','远视模型应加凸透镜还是凹透镜？','加入适当凸透镜，使光束提前会聚。')
add('telescope','lens','telescope','选择较长焦距物镜和较短焦距目镜。|调节两镜距离观察远物。|比较目视效果和光路中间像。','合适组合可增大远处物体对眼睛的视角。','折射望远镜由物镜成像，目镜再帮助观察中间像。','看得清远物不等于物像实际靠近|两镜间距需调节','严禁观察太阳','为什么望远镜常选长焦物镜和短焦目镜？','这种组合可获得较大的角放大作用，理想模型角放大率与两焦距之比有关。',aliases=['two-lenses-intro'])
add('water-drop-microscope','lens','microscope','在透明支撑面形成小水滴透镜。|放置细小物体并调整照明。|在上方加入放大镜，调节间距观察。','合适组合可看见更大的微小物体细节。','多个会聚元件可分级成像，但清晰度受到形状、照明和像差限制。','放大倍数不等于分辨率|水滴焦距不固定','不能宣称这种装置具有专业显微镜精度','水滴为什么可以作为简易透镜？','弯曲水面使光折射，形状适合时可产生会聚作用。')
